
-- Desde System

-- 1. Para no ensuciar los esquemas de SYS, ni de SYSTEM, vamos a crearnos un usuario
-- normal y le vamos a dar privilegios de DBA (asign�ndole el rol DBA a dicho usuario):
create user Practica_Indices identified by bd;
grant DBA to Practica_Indices;

-- Desde Practica_Indices (Hoja de Trabajo 1)

-- 2. Accedemos con el usuario Practica_Indices
-- Creamos una tabla Prueba2 y la rellenamos con los atributos CLAVE, DISPERSO,
-- CONCENTRADO, IDISPERSO, ICONCENTRADO, BCONCENTRADO. El campo CLAVE ser�
-- adem�s la clave primaria de esta tabla.

create table PRUEBA (
    CLAVE NUMBER(16, 0), 
    DISPERSO NUMBER(16, 0), 
    CONCENTRADO NUMBER(16, 0), 
    IDISPERSO NUMBER(16, 0), 
    ICONCENTRADO NUMBER(16, 0), 
    BCONCENTRADO NUMBER(16, 0),
    primary key (CLAVE)
);

-- Vamos a rellenar esta tabla seg�n las especificaciones anteriores con 100000 filas copiando y
-- ejecutando el siguiente c�digo PL/SQL:

DECLARE
I NUMBER(16,0);
R NUMBER(16,0);
BEGIN
FOR I IN 1..500000 LOOP
 R := DBMS_RANDOM.VALUE(1,1000000000);
 INSERT INTO PRUEBA VALUES(I, R, MOD(R,11), 1000000000-R, MOD(1000000000-R, 11),
MOD(2000000000-R, 11));
END LOOP;
END;
/

-- Hacemos un commit para guardar los cambios
Commit;

-- 3. Ahora vamos a crear los tres �ndices que hemos indicado sobre la tabla:
-- Uno denominado PID sobre el atributo IDISPERSO
create index PID on Prueba(idisperso);
-- Uno denominado PIC sobre el atributo ICONCENTRADO
create index PIC on Prueba(iconcentrado);
-- Uno denominado PBC de tipo BITMAP sobre el atributo BCONCENTRADO
create bitmap index PBC on Prueba(bconcentrado);

-- Ahora vamos a activar el modo AUTOTRACE y mejorar las estad�sticas, usando las sentencias:
SET AUTOTRACE ON;
ALTER SESSION SET STATISTICS_LEVEL='ALL';


-- 9. Construyamos ahora el �ndice sobre funci�n denominado FIX sobre la expresi�n
-- IDISPERSO+ICONCENTRADO.
create index FIX on Prueba(idisperso+iconcentrado);

