-- 6. Ahora procederemos a observar el principal inconveniente de los �ndices, su
-- penalizaci�n en operaciones de escritura que afecten atributos indexados.

ALTER SYSTEM FLUSH SHARED_POOL;
ALTER SYSTEM FLUSH BUFFER_CACHE;
UPDATE PRUEBA SET DISPERSO = DISPERSO + 7;
 -- 19324928  cell physical IO interconnect bytes

 
ALTER SYSTEM FLUSH SHARED_POOL;
ALTER SYSTEM FLUSH BUFFER_CACHE;
UPDATE PRUEBA SET IDISPERSO = IDISPERSO + 7;
-- 29835264  cell physical IO interconnect bytes


-- La segunda operacion es mas costosa pues realiza un mayor numero de lecturas de bloque y la cantidad de bytes totales leida y escrita es mayor.
-- Esto es debido a que los �ndices tienen problemas costosos en las sentencias de UPDATE, INSERT, etc, luego el atributo con indice
-- es peor.

